// --- Routing and transformation --------------------------------------------------

const gwTraefikRoutesCode = `http:
  routers:
    # Path prefix: /orders/... goes to orders, without the prefix.
    orders:
      entryPoints: [websecure]
      rule: PathPrefix(` + "`/orders`" + `)
      middlewares: [strip-orders]
      service: orders
    # Host: anything for admin.bb.internal goes to admin.
    admin:
      entryPoints: [websecure]
      rule: Host(` + "`admin.bb.internal`" + `)
      service: admin
    # The default route: matches everything, at the lowest priority.
    fallback:
      entryPoints: [websecure]
      rule: PathPrefix(` + "`/`" + `)
      priority: 1
      service: fallback
  middlewares:
    strip-orders:
      stripPrefix:
        prefixes: [/orders]`

const gwEnvoyRoutesCode = `virtual_hosts:
  # Envoy picks a virtual host by the Host header (with or without the port).
  - name: admin
    domains: ["admin.bb.internal", "admin.bb.internal:8443"]
    routes:
      - match: {prefix: /}
        route: {cluster: admin}
  - name: api
    domains: ["*"]
    # Routes are tried in order; the first match wins.
    routes:
      - match: {prefix: /orders/}
        route: {cluster: orders, prefix_rewrite: /}
      - match: {prefix: /}
        route: {cluster: fallback}`

const gwTransformCode = `http:
  middlewares:
    gateway-headers:
      headers:
        customRequestHeaders:
          X-Gateway: edge          # added to every request
          X-Debug: ""              # an empty value removes the header
        customResponseHeaders:
          Server: ""               # hide what answered
    v1-to-root:
      replacePathRegex:
        regex: ^/api/v1/(.*)
        replacement: /$1
    old-docs:
      redirectRegex:
        regex: ^https://([^/]+)/docs/(.*)
        replacement: https://${1}/help/${2}
        permanent: true`

const gwVersionCode = `# A header picks the version when the path does not say.
map $http_api_version $api_upstream {
    default be_v1;
    2       be_v2;
}

server {
    # By path: each version reaches its own backend, prefix stripped.
    location /v1/ {
        proxy_pass https://be_v1/;
        # Tell clients v1 is going away (RFC 9745 and RFC 8594).
        add_header Deprecation "@1798761600" always;
        add_header Sunset "Fri, 01 Jan 2027 00:00:00 GMT" always;
    }
    location /v2/ {
        proxy_pass https://be_v2/;
    }
    # By header: Api-Version: 2 reaches v2, anything else v1.
    location / {
        proxy_pass https://$api_upstream;
    }
}`

