// --- Authentication at the edge ----------------------------------------------------

const gwJWTCode = `http_filters:
  - name: envoy.filters.http.jwt_authn
    typed_config:
      '@type': type.googleapis.com/envoy.extensions.filters.http.jwt_authn.v3.JwtAuthentication
      providers:
        issuer:
          issuer: https://issuer.bb.internal:8443   # must equal the token's iss
          audiences: [orders]                       # the token's aud must name one
          # Public keys, fetched over verified TLS through the issuer cluster
          # and cached; a token's kid picks the key.
          remote_jwks:
            http_uri:
              uri: https://issuer.bb.internal:8443/.well-known/jwks.json
              cluster: issuer
              timeout: 2s
            cache_duration: 300s
          # Copy a verified claim into a header for the backend.
          claim_to_headers:
            - header_name: x-user
              claim_name: sub
      rules:
        # Every request needs a valid token from this provider.
        - match: {prefix: /}
          requires: {provider_name: issuer}
  - name: envoy.filters.http.router
    typed_config:
      '@type': type.googleapis.com/envoy.extensions.filters.http.router.v3.Router`

const gwForwardAuthCode = `http:
  routers:
    orders:
      entryPoints: [websecure]
      rule: PathPrefix(` + "`/`" + `)
      middlewares: [check-identity]
      service: orders
  middlewares:
    check-identity:
      forwardAuth:
        # Traefik asks this URL about every request first.
        address: https://auth.bb.internal:8443/check
        tls:
          ca: /etc/bb/ca.pem          # verify the auth service
        # On a 2xx, these headers from the auth answer are set on the request.
        authResponseHeaders:
          - X-User`

