// --- Rate limiting -------------------------------------------------------------------

const gwEnvoyRLCode = `http_filters:
  - name: envoy.filters.http.local_ratelimit
    typed_config:
      '@type': type.googleapis.com/envoy.extensions.filters.http.local_ratelimit.v3.LocalRateLimit
      stat_prefix: http_local_rate_limiter
      # A bucket of 10 tokens, topped up by 5 every second: bursts of 10,
      # then 5 requests a second.
      token_bucket:
        max_tokens: 10
        tokens_per_fill: 5
        fill_interval: 1s
      # Both default to 0% of requests: without them nothing is limited.
      filter_enabled:
        runtime_key: local_rate_limit_enabled
        default_value: {numerator: 100, denominator: HUNDRED}
      filter_enforced:
        runtime_key: local_rate_limit_enforced
        default_value: {numerator: 100, denominator: HUNDRED}
  - name: envoy.filters.http.router
    typed_config:
      '@type': type.googleapis.com/envoy.extensions.filters.http.router.v3.Router`

const gwNginxRLCode = `http {
    # One counter per client address, at 5 requests a second (one every
    # 200 ms), kept in 10 MB of memory shared by the workers.
    limit_req_zone $binary_remote_addr zone=perclient:10m rate=5r/s;
    # The default answer is 503.
    limit_req_status 429;

    server {
        location / {
            # Up to 10 requests above the rate wait their turn; more are rejected.
            limit_req zone=perclient burst=10;
            # nodelay: serve those 10 at once; their slots still free at the rate.
            # limit_req zone=perclient burst=10 nodelay;
            proxy_pass https://be_api;
        }
    }
}`

const gwTraefikRLCode = `http:
  middlewares:
    per-client:
      rateLimit:
        average: 5        # tokens added per period
        period: 1s
        burst: 10         # the bucket's size
        # Whose bucket: by default the client's address; here a header.
        sourceCriterion:
          requestHeaderName: X-Client-Id`

const gwWindowCode = `// Fixed window: one counter per key per minute.
window := now.Truncate(time.Minute)
if counts[key][window] >= limit { reject() }
counts[key][window]++

// Sliding window counter: weigh the previous minute by how much of it
// still overlaps the last 60 seconds.
prev := window.Add(-time.Minute)
elapsed := now.Sub(window).Seconds() / 60
estimate := float64(counts[key][prev])*(1-elapsed) + float64(counts[key][window])
if estimate >= limit { reject() }`

