// --- Resilience --------------------------------------------------------------------

const gwResilienceCode = `routes:
  - match: {prefix: /}
    route:
      cluster: orders
      # The whole exchange, every try included. The default is 15s.
      timeout: 3s
      retry_policy:
        retry_on: 5xx,reset,connect-failure
        num_retries: 2              # the default is 1
        per_try_timeout: 1s
        # Jittered exponential backoff between tries (default 25ms base).
        retry_back_off: {base_interval: 0.1s, max_interval: 1s}
clusters:
  - name: orders
    circuit_breakers:
      thresholds:
        - priority: DEFAULT
          max_connections: 100        # each defaults to 1024
          max_pending_requests: 10
          max_requests: 50
          # Retries in flight may be at most 20% of requests in flight,
          # but at least 3. Replaces max_retries when set.
          retry_budget:
            budget_percent: {value: 20.0}
            min_retry_concurrency: 3`

const gwTraefikBreakerCode = `http:
  middlewares:
    orders-breaker:
      circuitBreaker:
        # Open when more than a quarter of answers are 5xx, or 10% are network errors.
        expression: ResponseCodeRatio(500, 600, 0, 600) > 0.25 || NetworkErrorRatio() > 0.10
        checkPeriod: 100ms
        fallbackDuration: 10s   # open: answer 503 without calling the service
        recoveryDuration: 10s   # recovering: let traffic back in gradually
    orders-retry:
      retry:
        attempts: 3
        initialInterval: 100ms`

