// --- Backend for frontend -------------------------------------------------------------

const gwBFFCode = `// One handler, two services in parallel, one merged answer.
func dashboard(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 800*time.Millisecond)
	defer cancel()
	var profile Profile
	var orders []Order
	g, ctx := errgroup.WithContext(ctx)
	g.Go(func() error { return get(ctx, usersURL+"/me", &profile) })
	g.Go(func() error { return get(ctx, ordersURL+"/recent", &orders) })
	if err := g.Wait(); err != nil {
		http.Error(w, "upstream failed", http.StatusBadGateway)
		return
	}
	json.NewEncoder(w).Encode(Dashboard{Profile: profile, Orders: orders})
}`

