// --- gRPC ---------------------------------------------------------------------------

const gwGRPCRoutesCode = `routes:
  # gRPC paths are /<package>.<Service>/<Method>: one method by exact path,
  # with its own deadline, before the rule for its whole service.
  - match: {path: /catalog.v1.Catalog/Search, grpc: {}}
    route:
      cluster: catalog
      max_stream_duration:
        # Used when the call carries no grpc-timeout header.
        max_stream_duration: 0.5s
        # When it does, use the client's deadline, but never more than this.
        grpc_timeout_header_max: 0.5s
  # A whole service by prefix: honour the client's deadline, up to 5s.
  - match: {prefix: /catalog.v1.Catalog/, grpc: {}}
    route: {cluster: catalog, max_stream_duration: {grpc_timeout_header_max: 5s}}
  - match: {prefix: /orders.v1.Orders/, grpc: {}}
    route: {cluster: orders, max_stream_duration: {grpc_timeout_header_max: 5s}}`

const gwGRPCClusterCode = `clusters:
  - name: orders
    # gRPC needs HTTP/2 to the backend; Envoy speaks HTTP/1.1 to a cluster
    # unless told otherwise.
    typed_extension_protocol_options:
      envoy.extensions.upstreams.http.v3.HttpProtocolOptions:
        '@type': type.googleapis.com/envoy.extensions.upstreams.http.v3.HttpProtocolOptions
        explicit_http_config:
          http2_protocol_options: {}
    transport_socket:
      name: envoy.transport_sockets.tls
      typed_config:
        '@type': type.googleapis.com/envoy.extensions.transport_sockets.tls.v3.UpstreamTlsContext
        sni: orders.bb.internal
        common_tls_context:
          alpn_protocols: [h2]
          validation_context:
            trusted_ca: {filename: /etc/bb/ca.pem}
            # Verify the name too: SNI only asks for a certificate, and any
            # certificate the lab CA signed would pass trusted_ca alone.
            match_typed_subject_alt_names:
              - san_type: DNS
                matcher: {exact: orders.bb.internal}`

